<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Trabajá con nosotros</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="<?= URLROOT ?>/css/style.css"></head><body class="bg-light"><main class="container py-5"><header class="mb-5"><span class="text-uppercase text-primary fw-semibold">Oportunidades</span><h1 class="display-5 fw-bold">Trabajá con nosotros</h1><p class="lead text-secondary">Conocé las búsquedas abiertas y postulá tu experiencia.</p></header><div class="row g-4"><?php foreach($d['vacancies'] as $v): ?><article class="col-md-6"><div class="card h-100 shadow-sm border-0"><div class="card-body p-4"><small class="text-secondary"><?= htmlspecialchars($v->company_name) ?><?= $v->branch_name?' · '.htmlspecialchars($v->branch_name):'' ?></small><h2 class="h4 mt-2"><?= htmlspecialchars($v->title) ?></h2><p><?= htmlspecialchars(mb_strimwidth(strip_tags($v->description),0,180,'…')) ?></p><a class="btn btn-primary" href="<?= URLROOT ?>/careers/vacancy/<?= rawurlencode($v->slug) ?>">Ver vacante</a></div></div></article><?php endforeach; ?><?php if(!$d['vacancies']): ?><p class="text-secondary">No hay búsquedas abiertas en este momento.</p><?php endif; ?></div></main></body></html>
